// Renders the token sections of /design-system from assets/js/tokens.js (generated by `npm run tokens`).
// Tables follow the active theme (html[data-theme]) and re-render when the nav switch flips it.
(() => {
  const data = window.CBJ_TOKENS;
  if (!data) return;
  const root = document.documentElement;
  const defaultTheme = data.themes.find((t) => t.default) || data.themes[0];
  const core = defaultTheme.tokens.filter((t) => t.tier === 'core');
  const $ = (sel) => document.querySelector(sel);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const set = (sel, html) => { const el = $(sel); if (el) el.innerHTML = html; };
  const setAll = (sel, html) => document.querySelectorAll(sel).forEach((el) => { el.innerHTML = html; });

  const themeTokens = (theme) => [...core, ...theme.tokens.filter((t) => t.tier !== 'core')];
  const activeTheme = () => data.themes.find((t) => t.id === root.dataset.theme) || defaultTheme;

  /* ---------- contrast (WCAG 2.x relative luminance) ---------- */
  const rgb = (hex) => {
    const h = hex.replace('#', '');
    if (!/^[0-9a-f]{6}$/i.test(h)) return null; // skip alpha / non-hex
    return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);
  };
  const lum = (c) => {
    const [r, g, b] = c.map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const ratio = (a, b) => {
    const A = rgb(a), B = rgb(b);
    if (!A || !B) return null;
    const [hi, lo] = [lum(A), lum(B)].sort((x, y) => y - x);
    return (hi + 0.05) / (lo + 0.05);
  };
  // [foreground, background, kind, where it's used]
  const PAIRS = [
    ['text.primary', 'surface.page', 'text', 'Headings, body'],
    ['text.secondary', 'surface.page', 'text', 'Descriptions, lead'],
    ['text.tertiary', 'surface.page', 'text', 'Meta, readouts'],
    ['text.tertiary', 'surface.raised', 'text', 'Meta tiles'],
    ['text.tertiary', 'surface.void', 'text', 'Footer'],
    ['component.tag.fg', 'component.tag.bg', 'text', 'Tags'],
    ['text.accent', 'surface.page', 'text', 'Active nav, accent text'],
    ['text.highlight', 'surface.page', 'text', 'Prices, live readouts'],
    ['component.button.fg', 'component.button.bg', 'text', 'Primary button'],
    ['component.button.fg', 'component.button.bg-hover', 'text', 'Primary button, hover'],
    ['component.theme-toggle.icon-active', 'component.theme-toggle.thumb', 'ui', 'Theme toggle icon'],
    ['border.strong', 'surface.page', 'ui', 'Ghost button & input borders'],
    ['accent.primary', 'surface.page', 'ui', 'Dots, frame corners, rules'],
    ['focus.ring', 'surface.page', 'ui', 'Focus ring'],
  ];
  const grade = (r, kind) => {
    if (r == null) return '<span class="ds-grade">n/a</span>';
    if (kind === 'ui') return r >= 3 ? '<span class="ds-grade ds-grade--pass">UI ✓</span>' : '<span class="ds-grade ds-grade--fail">UI ✗</span>';
    if (r >= 7) return '<span class="ds-grade ds-grade--pass">AAA</span>';
    if (r >= 4.5) return '<span class="ds-grade ds-grade--pass">AA</span>';
    return '<span class="ds-grade ds-grade--fail">Fail</span>';
  };
  const renderContrast = () => {
    const maps = data.themes.map((t) => ({ theme: t, map: new Map(themeTokens(t).map((x) => [x.path, x.value])) }));
    const head = maps.map(({ theme }) => `<th>${esc(theme.name)}</th>`).join('');
    const rows = PAIRS.map(([fg, bg, kind, use]) => {
      const cells = maps.map(({ map }) => {
        const f = map.get(fg), b = map.get(bg);
        const r = f && b ? ratio(f, b) : null;
        return `<td><span class="ds-pair" style="color:${esc(f)};background:${esc(b)}">Aa</span><code>${r ? r.toFixed(2) : '—'}</code> ${grade(r, kind)}</td>`;
      }).join('');
      return `<tr><td><code>${esc(fg.replace('component.', ''))}</code><br><span class="mono text-tertiary">on ${esc(bg.replace('component.', ''))} · ${esc(use)}</span></td>${cells}</tr>`;
    }).join('');
    set('[data-ds="contrast"]', `<div class="ds-table-wrap"><table class="ds-table"><thead><tr><th>Pair</th>${head}</tr></thead><tbody>${rows}</tbody></table></div>`);
  };

  /* ---------- tables ---------- */
  const swatch = (t) => `<button type="button" class="ds-swatch" data-copy="var(${t.cssVar})" title="Copy var(${t.cssVar})">
      <span class="ds-swatch__chip"><span style="background:${t.value}"></span></span>
      <span class="ds-swatch__meta">
        <span class="meta">${esc(t.path.replace(/^color\./, ''))}</span>
        <span class="mono text-tertiary">${esc(t.value)}</span>
        ${t.description ? `<span class="mono text-tertiary">${esc(t.description)}</span>` : ''}
      </span>
    </button>`;
  const row = (t) => `<tr>
      <td>${t.type === 'color' ? `<span class="ds-mini" style="background:${t.value}"></span>` : ''}<code>${esc(t.cssVar)}</code>${t.overridden ? ' <span class="text-accent" title="Overridden by this theme">◆</span>' : ''}</td>
      <td class="ds-alias">${t.alias ? esc('{' + t.alias + '}') : '—'}</td>
      <td><code>${esc(t.value)}</code></td>
      <td class="text-secondary">${esc(t.description || '')}</td>
    </tr>`;
  const table = (rows) => `<div class="ds-table-wrap"><table class="ds-table">
      <thead><tr><th>Variable</th><th>Alias</th><th>Resolved</th><th>Note</th></tr></thead>
      <tbody>${rows.map(row).join('')}</tbody></table></div>`;

  const render = () => {
    const theme = activeTheme();
    const all = themeTokens(theme);
    const by = (fn) => all.filter(fn);
    setAll('[data-ds="theme-name"]', esc(theme.name));
    set('[data-ds="generated"]', esc(new Date(data.generated).toLocaleString()));
    set('[data-ds="count"]', String(core.length + data.themes.reduce((n, t) => n + t.tokens.filter((x) => x.tier !== 'core' && (t.default || x.overridden)).length, 0)));

    set('[data-ds="core-colors"]', by((t) => t.tier === 'core' && t.type === 'color').map(swatch).join(''));
    set('[data-ds="semantic-colors"]', table(by((t) => t.tier === 'semantic' && t.type === 'color')));
    set('[data-ds="semantic-other"]', table(by((t) => t.tier === 'semantic' && t.type !== 'color')));
    set('[data-ds="component-tokens"]', table(by((t) => t.tier === 'component')));
    set('[data-ds="core-type"]', table(by((t) => t.tier === 'core' && t.path.startsWith('font.'))));
    set('[data-ds="core-motion"]', table(by((t) => t.path.startsWith('motion.') || t.path.startsWith('blur.') || t.path.startsWith('size.'))));

    const px = (v) => parseFloat(v) || 0;
    const space = by((t) => t.path.startsWith('space.'));
    const max = Math.max(...space.map((t) => px(t.value)));
    set('[data-ds="space"]', space.map((t) => `<div class="ds-scale__row">
        <code class="mono">${esc(t.cssVar)}</code><span class="mono text-tertiary">${esc(t.value)}</span>
        <span class="ds-scale__bar" style="width:${(px(t.value) / max) * 100}%"></span></div>`).join(''));
    set('[data-ds="radius"]', by((t) => t.path.startsWith('radius.')).map((t) =>
      `<div style="border-radius:${t.value}"><span class="mono">${esc(t.path.replace('radius.', ''))}</span></div>`).join(''));
  };

  render();
  renderContrast();
  window.addEventListener('cbj:themechange', render);

  // Click to copy
  const toast = $('.ds-toast');
  document.addEventListener('click', async (e) => {
    const el = e.target.closest('[data-copy]');
    if (!el) return;
    try {
      await navigator.clipboard.writeText(el.dataset.copy);
      if (toast) {
        toast.textContent = `Copied ${el.dataset.copy}`;
        toast.dataset.show = 'true';
        clearTimeout(toast._t);
        toast._t = setTimeout(() => { toast.dataset.show = 'false'; }, 1400);
      }
    } catch { /* clipboard unavailable (e.g. file://) */ }
  });
})();
